mkitem!{mkimpl!{# [stable (feature = "array_into_iter_impl" , since = "1.53.0")] impl < T , const N : usize > IntoIterator for [T ; N] { type Item = T ; type IntoIter = IntoIter < T , N > ; # [doc = " Creates a consuming iterator, that is, one that moves each value out of"] # [doc = " the array (from start to end)."] # [doc = ""] # [doc = " The array cannot be used after calling this unless `T` implements"] # [doc = " `Copy`, so the whole array is copied."] # [doc = ""] # [doc = " Arrays have special behavior when calling `.into_iter()` prior to the"] # [doc = " 2021 edition -- see the [array] Editions section for more information."] # [doc = ""] # [doc = " [array]: prim@array"] # [inline] fn into_iter (self) -> Self :: IntoIter { let data : [MaybeUninit < T > ; N] = unsafe { transmute_unchecked (self) } ; let inner = unsafe { InnerSized :: new_unchecked (IndexRange :: zero_to (N) , data) } ; IntoIter { inner } } }}}
mkitem!{mkimpl!{impl < T , const N : usize > IntoIter < T , N > { # [doc = " Creates a new iterator over the given `array`."] # [stable (feature = "array_value_iter" , since = "1.51.0")] # [deprecated (since = "1.59.0" , note = "use `IntoIterator::into_iter` instead")] pub fn new (array : [T ; N]) -> Self { IntoIterator :: into_iter (array) } # [doc = " Creates an iterator over the elements in a partially-initialized buffer."] # [doc = ""] # [doc = " If you have a fully-initialized array, then use [`IntoIterator`]."] # [doc = " But this is useful for returning partial results from unsafe code."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " - The `buffer[initialized]` elements must all be initialized."] # [doc = " - The range must be canonical, with `initialized.start <= initialized.end`."] # [doc = " - The range must be in-bounds for the buffer, with `initialized.end <= N`."] # [doc = "   (Like how indexing `[0][100..100]` fails despite the range being empty.)"] # [doc = ""] # [doc = " It's sound to have more elements initialized than mentioned, though that"] # [doc = " will most likely result in them being leaked."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(array_into_iter_constructors)]"] # [doc = " #![feature(maybe_uninit_uninit_array_transpose)]"] # [doc = " use std::array::IntoIter;"] # [doc = " use std::mem::MaybeUninit;"] # [doc = ""] # [doc = " # // Hi!  Thanks for reading the code. This is restricted to `Copy` because"] # [doc = " # // otherwise it could leak. A fully-general version this would need a drop"] # [doc = " # // guard to handle panics from the iterator, but this works for an example."] # [doc = " fn next_chunk<T: Copy, const N: usize>("] # [doc = "     it: &mut impl Iterator<Item = T>,"] # [doc = " ) -> Result<[T; N], IntoIter<T, N>> {"] # [doc = "     let mut buffer = [const { MaybeUninit::uninit() }; N];"] # [doc = "     let mut i = 0;"] # [doc = "     while i < N {"] # [doc = "         match it.next() {"] # [doc = "             Some(x) => {"] # [doc = "                 buffer[i].write(x);"] # [doc = "                 i += 1;"] # [doc = "             }"] # [doc = "             None => {"] # [doc = "                 // SAFETY: We've initialized the first `i` items"] # [doc = "                 unsafe {"] # [doc = "                     return Err(IntoIter::new_unchecked(buffer, 0..i));"] # [doc = "                 }"] # [doc = "             }"] # [doc = "         }"] # [doc = "     }"] # [doc = ""] # [doc = "     // SAFETY: We've initialized all N items"] # [doc = "     unsafe { Ok(buffer.transpose().assume_init()) }"] # [doc = " }"] # [doc = ""] # [doc = " let r: [_; 4] = next_chunk(&mut (10..16)).unwrap();"] # [doc = " assert_eq!(r, [10, 11, 12, 13]);"] # [doc = " let r: IntoIter<_, 40> = next_chunk(&mut (10..16)).unwrap_err();"] # [doc = " assert_eq!(r.collect::<Vec<_>>(), vec![10, 11, 12, 13, 14, 15]);"] # [doc = " ```"] # [unstable (feature = "array_into_iter_constructors" , issue = "91583")] # [inline] pub const unsafe fn new_unchecked (buffer : [MaybeUninit < T > ; N] , initialized : Range < usize > ,) -> Self { let alive = unsafe { IndexRange :: new_unchecked (initialized . start , initialized . end) } ; let inner = unsafe { InnerSized :: new_unchecked (alive , buffer) } ; IntoIter { inner } } # [doc = " Creates an iterator over `T` which returns no elements."] # [doc = ""] # [doc = " If you just need an empty iterator, then use"] # [doc = " [`iter::empty()`](crate::iter::empty) instead."] # [doc = " And if you need an empty array, use `[]`."] # [doc = ""] # [doc = " But this is useful when you need an `array::IntoIter<T, N>` *specifically*."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(array_into_iter_constructors)]"] # [doc = " use std::array::IntoIter;"] # [doc = ""] # [doc = " let empty = IntoIter::<i32, 3>::empty();"] # [doc = " assert_eq!(empty.len(), 0);"] # [doc = " assert_eq!(empty.as_slice(), &[]);"] # [doc = ""] # [doc = " let empty = IntoIter::<std::convert::Infallible, 200>::empty();"] # [doc = " assert_eq!(empty.len(), 0);"] # [doc = " ```"] # [doc = ""] # [doc = " `[1, 2].into_iter()` and `[].into_iter()` have different types"] # [doc = " ```should_fail,edition2021"] # [doc = " #![feature(array_into_iter_constructors)]"] # [doc = " use std::array::IntoIter;"] # [doc = ""] # [doc = " pub fn get_bytes(b: bool) -> IntoIter<i8, 4> {"] # [doc = "     if b {"] # [doc = "         [1, 2, 3, 4].into_iter()"] # [doc = "     } else {"] # [doc = "         [].into_iter() // error[E0308]: mismatched types"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " But using this method you can get an empty iterator of appropriate size:"] # [doc = " ```edition2021"] # [doc = " #![feature(array_into_iter_constructors)]"] # [doc = " use std::array::IntoIter;"] # [doc = ""] # [doc = " pub fn get_bytes(b: bool) -> IntoIter<i8, 4> {"] # [doc = "     if b {"] # [doc = "         [1, 2, 3, 4].into_iter()"] # [doc = "     } else {"] # [doc = "         IntoIter::empty()"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " assert_eq!(get_bytes(true).collect::<Vec<_>>(), vec![1, 2, 3, 4]);"] # [doc = " assert_eq!(get_bytes(false).collect::<Vec<_>>(), vec![]);"] # [doc = " ```"] # [unstable (feature = "array_into_iter_constructors" , issue = "91583")] # [inline] pub const fn empty () -> Self { let inner = InnerSized :: empty () ; IntoIter { inner } } # [doc = " Returns an immutable slice of all elements that have not been yielded"] # [doc = " yet."] # [stable (feature = "array_value_iter" , since = "1.51.0")] # [inline] pub fn as_slice (& self) -> & [T] { self . unsize () . as_slice () } # [doc = " Returns a mutable slice of all elements that have not been yielded yet."] # [stable (feature = "array_value_iter" , since = "1.51.0")] # [inline] pub fn as_mut_slice (& mut self) -> & mut [T] { self . unsize_mut () . as_mut_slice () } }}}
